import org.springframework.amqp.core.*;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class RabbitMQConfig {

    public static final String DIRECT_EXCHANGE = "order.direct";
    public static final String TOPIC_EXCHANGE = "order.topic";
    public static final String FANOUT_EXCHANGE = "order.fanout";
    public static final String HEADERS_EXCHANGE = "order.headers";

    @Bean
    public DirectExchange directExchange() {
        return new DirectExchange(DIRECT_EXCHANGE);
    }

    @Bean
    public TopicExchange topicExchange() {
        return new TopicExchange(TOPIC_EXCHANGE);
    }

    @Bean
    public FanoutExchange fanoutExchange() {
        return new FanoutExchange(FANOUT_EXCHANGE);
    }

    @Bean
    public HeadersExchange headersExchange() {
        return new HeadersExchange(HEADERS_EXCHANGE);
    }

    @Bean
    public Binding topicBinding(Queue ordersQueue, TopicExchange topicExchange) {
        return BindingBuilder.bind(ordersQueue).to(topicExchange).with("order.us.#");
    }

    @Bean
    public Binding headersBinding(Queue auditQueue, HeadersExchange headersExchange) {
        return BindingBuilder.bind(auditQueue).to(headersExchange)
                .whereAll("format", "type").match();
    }
}
